const LEAGUES = [
  { id: "mon-am", name: "Monday AM", weekday: 1 },
  { id: "mon-eve", name: "Monday Evening", weekday: 1 },
  { id: "tue-am", name: "Tuesday AM", weekday: 2 },
  { id: "wed-pm", name: "Wednesday PM", weekday: 3 },
  { id: "thu-eve", name: "Thursday Evening", weekday: 4 },
  { id: "fri-am", name: "Friday AM", weekday: 5 },
];

// Number of match-weeks in the season for each league size. Every week, teams
// pair up across up to 4 rinks (floor(size/2) matches/week; odd sizes have one
// team on a bye each week). Season calendar allows up to 24 weeks overall.
const SEASON_WEEKS = { 6: 20, 7: 24, 8: 21 };
const SEASON_MAX_WEEKS = 24;
const RINKS = [1, 2, 3, 4];
const ADMIN_PASSWORD = "skip";
const LEADER_PASSWORD = "shot";
const STORAGE_KEY = "hatfield-indoor-data";
const CLUB_LOGO = "data:image/png;base64,";

function defaultTeams(n) {
  return Array.from({ length: n }, (_, i) => `Team ${i + 1}`);
}

function defaultSeasonYear() {
  const now = new Date();
  // The Oct-Mar season finishes at the end of March, so from April onward we're
  // already into the lead-up to the next season and should label it as such.
  return now.getMonth() >= 3 ? now.getFullYear() : now.getFullYear() - 1;
}

function emptyLeague() {
  return { size: null, teams: [], matches: [], locked: false, calendar: { startYear: defaultSeasonYear(), excluded: [] } };
}

function toIso(d) {
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, "0");
  const day = String(d.getDate()).padStart(2, "0");
  return `${y}-${m}-${day}`;
}

// All dates matching `weekday` (0=Sun..6=Sat) from 1 Oct startYear to 31 Mar the following year.
function seasonCandidateDates(weekday, startYear) {
  const start = new Date(startYear, 9, 1);
  const end = new Date(startYear + 1, 2, 31);
  const dates = [];
  const d = new Date(start);
  d.setDate(d.getDate() + ((weekday - d.getDay() + 7) % 7));
  while (d <= end) {
    dates.push(toIso(d));
    d.setDate(d.getDate() + 7);
  }
  return dates;
}

function formatDateLong(iso) {
  return new Date(iso + "T00:00:00").toLocaleDateString(undefined, {
    weekday: "short", day: "numeric", month: "short", year: "numeric",
  });
}

function emptyData() {
  const leagues = {};
  LEAGUES.forEach((l) => (leagues[l.id] = emptyLeague()));
  return { leagues, autoBackup: false, lastAutoBackupDate: null, seasonYear: defaultSeasonYear() };
}

function uid() {
  return "m" + Date.now().toString(36) + Math.random().toString(36).slice(2, 7);
}

function shuffle(arr) {
  const a = [...arr];
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

/* Standard circle-method round robin. Returns array of rounds,
   each round an array of [teamA, teamB] index pairs (no repeats within a round). */
function circleRounds(n) {
  const hasBye = n % 2 !== 0;
  const arr = hasBye ? [...Array(n).keys(), -1] : [...Array(n).keys()];
  const m = arr.length;
  const fixed = arr[0];
  let rotating = arr.slice(1);
  const rounds = [];
  for (let r = 0; r < m - 1; r++) {
    const roundArr = [fixed, ...rotating];
    const pairs = [];
    for (let i = 0; i < m / 2; i++) {
      const a = roundArr[i];
      const b = roundArr[m - 1 - i];
      if (a !== -1 && b !== -1) pairs.push([a, b]);
    }
    rounds.push(pairs);
    rotating = [rotating[rotating.length - 1], ...rotating.slice(0, -1)];
  }
  return rounds;
}

/* Build a season's fixtures for n teams over `weeksNeeded` match-weeks.
   Every week is one round of the round-robin rotation: floor(n/2) matches,
   with no team playing twice in the same week (odd sizes get one bye/week).
   Once a full lap of the rotation is used up, it starts again (reversing
   home/away on alternate laps) until the season length is reached, so teams
   meet each other roughly the same number of times across the season.
   Rinks are drawn at random within each week. */
function generateFixtures(n, weeksNeeded) {
  const rounds = circleRounds(n); // one "lap" = rounds.length weeks
  const schedule = [];
  let lap = 0;
  while (schedule.length < weeksNeeded) {
    const lapRounds = rounds.map((r) => (lap % 2 === 1 ? r.map(([a, b]) => [b, a]) : r));
    const shuffledLap = shuffle(lapRounds);
    for (const roundPairs of shuffledLap) {
      if (schedule.length >= weeksNeeded) break;
      schedule.push(roundPairs);
    }
    lap++;
    if (lap > 20) break; // safety valve
  }

  const matches = [];
  schedule.forEach((weekPairs, weekIdx) => {
    const rinkDraw = shuffle(RINKS);
    weekPairs.forEach((pair, i) => {
      matches.push({
        id: uid(),
        week: weekIdx,
        home: pair[0],
        away: pair[1],
        rink: rinkDraw[i],
        date: "",
        homeScore: null,
        awayScore: null,
        played: false,
      });
    });
  });

  return { matches, weekCount: schedule.length };
}

function computeStandings(league) {
  if (!league.size) return [];
  const rows = league.teams.map((name, idx) => ({
    idx, name, p: 0, w: 0, d: 0, l: 0, f: 0, a: 0, pts: 0,
  }));
  league.matches.forEach((m) => {
    if (!m.played) return;
    const h = rows[m.home];
    const aw = rows[m.away];
    if (!h || !aw) return;
    h.p++; aw.p++;
    h.f += m.homeScore; h.a += m.awayScore;
    aw.f += m.awayScore; aw.a += m.homeScore;
    if (m.homeScore > m.awayScore) { h.w++; aw.l++; h.pts += 2; }
    else if (m.homeScore < m.awayScore) { aw.w++; h.l++; aw.pts += 2; }
    else { h.d++; aw.d++; h.pts += 1; aw.pts += 1; }
  });
  rows.forEach((r) => (r.diff = r.f - r.a));
  rows.sort((a, b) => b.pts - a.pts || b.diff - a.diff || b.f - a.f || a.name.localeCompare(b.name));
  return rows;
}

/* ------------------------------------------------------------------ */
/* Storage helpers                                                     */
/* ------------------------------------------------------------------ */

async function loadRemote() {
  try {
    const res = await window.storage.get(STORAGE_KEY, true);
    if (res && res.value) return JSON.parse(res.value);
  } catch (e) {
    /* not found or storage unavailable */
  }
  return null;
}

async function saveRemote(data) {
  try {
    await window.storage.set(STORAGE_KEY, JSON.stringify(data), true);
    return true;
  } catch (e) {
    return false;
  }
}

async function saveBackup(data, label) {
  const ts = new Date().toISOString();
  await window.storage.set(`hatfield-backup-${ts}`, JSON.stringify(data), true);
  let index = [];
  try {
    const res = await window.storage.get("hatfield-backups-index", true);
    index = res ? JSON.parse(res.value) : [];
  } catch (e) { /* no index yet */ }
  const nextIndex = [{ ts, label: label || "" }, ...index].slice(0, 30);
  await window.storage.set("hatfield-backups-index", JSON.stringify(nextIndex), true);
  return ts;
}

