function RinkBadge({ n }) {
  return (
    <span className="inline-flex items-center justify-center gap-1 px-2 py-1 rounded-full bg-amber-600 text-white text-xs font-bold shrink-0">
      Rink {n ?? "-"}
    </span>
  );
}

function Toast({ message, onDone }) {
  useEffect(() => {
    const t = setTimeout(onDone, 2600);
    return () => clearTimeout(t);
  }, [onDone]);
  if (!message) return null;
  return (
    <div className="fixed bottom-4 left-1/2 -translate-x-1/2 bg-stone-900 text-amber-50 px-4 py-2 rounded-full shadow-lg text-sm z-50 flex items-center gap-2">
      <Check size={14} className="text-emerald-400" /> {message}
    </div>
  );
}

/* ------------------------------------------------------------------ */
/* Main App                                                             */
/* ------------------------------------------------------------------ */

export default function App() {
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [view, setView] = useState("public"); // public | admin-login | admin | leader-login | leader
  const [activeLeagueId, setActiveLeagueId] = useState(LEAGUES[0].id);
  const [pwInput, setPwInput] = useState("");
  const [pwError, setPwError] = useState("");
  const [toast, setToast] = useState("");
  const [printMode, setPrintMode] = useState(null); // null | 'single' | 'all'
  const [printLeagueId, setPrintLeagueId] = useState(null);
  const dataRef = useRef(null);
  const editingRef = useRef(false);

  const flash = (msg) => setToast(msg);

  const printLeague = (leagueId) => { setPrintLeagueId(leagueId); setPrintMode("single"); };
  const printAllLeagues = () => setPrintMode("all");

  useEffect(() => {
    if (!printMode) return;
    const t = setTimeout(() => window.print(), 80);
    const handleAfterPrint = () => setPrintMode(null);
    window.addEventListener("afterprint", handleAfterPrint);
    return () => { clearTimeout(t); window.removeEventListener("afterprint", handleAfterPrint); };
  }, [printMode]);

  useEffect(() => {
    (async () => {
      let remote = await loadRemote();
      if (!remote) {
        remote = emptyData();
        await saveRemote(remote);
      }
      dataRef.current = remote;
      setData(remote);
      setLoading(false);
    })();
  }, []);

  // light polling so the public standings/fixtures pages "auto update"
  useEffect(() => {
    const interval = setInterval(async () => {
      if (editingRef.current) return;
      const remote = await loadRemote();
      if (remote && JSON.stringify(remote) !== JSON.stringify(dataRef.current)) {
        dataRef.current = remote;
        setData(remote);
      }
    }, 7000);
    return () => clearInterval(interval);
  }, []);

  const persist = useCallback(async (next) => {
    dataRef.current = next;
    setData(next);
    await saveRemote(next);
  }, []);

  if (loading || !data) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-emerald-900 text-amber-50 font-serif">
        <div className="flex items-center gap-3">
          <RefreshCw className="animate-spin" size={20} /> Loading the club board…
        </div>
      </div>
    );
  }

  const activeLeague = data.leagues[activeLeagueId];

  return (
    <div className="min-h-screen bg-stone-50 text-stone-900 font-sans">
      <style>{`
        @media print {
          #app-screen-ui { display: none !important; }
          .print-sheet { display: block !important; }
        }
        .print-sheet { display: none; }
      `}</style>
      <div id="app-screen-ui">
        <Masthead
          view={view}
          setView={setView}
          onLogout={() => { setView("public"); setPwInput(""); setPwError(""); }}
          data={data}
        />

        {view === "public" && (
          <PublicView
            data={data}
            activeLeagueId={activeLeagueId}
            setActiveLeagueId={setActiveLeagueId}
            onPrintLeague={printLeague}
          />
        )}

        {(view === "admin-login" || view === "leader-login") && (
          <LoginScreen
            role={view === "admin-login" ? "admin" : "leader"}
            pwInput={pwInput}
            setPwInput={setPwInput}
            pwError={pwError}
            onBack={() => { setView("public"); setPwInput(""); setPwError(""); }}
            onSubmit={() => {
              const expected = view === "admin-login" ? ADMIN_PASSWORD : LEADER_PASSWORD;
              if (pwInput === expected) {
                setView(view === "admin-login" ? "admin" : "leader");
                setPwInput(""); setPwError("");
              } else {
                setPwError("That password doesn't match. Try again.");
              }
            }}
          />
        )}

        {view === "admin" && (
          <AdminPanel
            data={data}
            persist={persist}
            activeLeagueId={activeLeagueId}
            setActiveLeagueId={setActiveLeagueId}
            flash={flash}
            editingRef={editingRef}
            onPrintLeague={printLeague}
            onPrintAllLeagues={printAllLeagues}
          />
        )}

        {view === "leader" && (
          <ResultsEntry
            data={data}
            persist={persist}
            activeLeagueId={activeLeagueId}
            setActiveLeagueId={setActiveLeagueId}
            flash={flash}
            canUnlock={false}
            editingRef={editingRef}
          />
        )}

        <Toast message={toast} onDone={() => setToast("")} />
        <footer className="text-center text-xs text-stone-400 py-8">
          Hatfield Indoor Bowls Leagues
        </footer>
      </div>

      {printMode === "single" && printLeagueId && (
        <PrintableFixtures data={data} leagueId={printLeagueId} />
      )}
      {printMode === "all" && (
        <div>
          {LEAGUES.filter((l) => data.leagues[l.id].size).map((l, i) => (
            <PrintableFixtures
              key={l.id}
              data={data}
              leagueId={l.id}
              pageBreakBefore={i > 0}
            />
          ))}
        </div>
      )}
    </div>
  );
}

