/* ------------------------------------------------------------------ */
/* Print view                                                          */
/* ------------------------------------------------------------------ */

function PrintableFixtures({ data, leagueId, halfPage, pageBreakBefore }) {
  const league = data.leagues[leagueId];
  const meta = LEAGUES.find((l) => l.id === leagueId);
  if (!league || !league.size) return null;
  const startYear = league.calendar?.startYear ?? defaultSeasonYear();
  const seasonLabel = `${startYear}/${String(startYear + 1).slice(-2)}`;

  const weeks = {};
  league.matches.forEach((m) => {
    weeks[m.week] = weeks[m.week] || [];
    weeks[m.week].push(m);
  });
  const weekNums = Object.keys(weeks).map(Number).sort((a, b) => a - b);
  // busier leagues (more total rows) get an extra column so a half-page sheet still fits everything;
  // a full sheet only needs 2 columns once the season runs long.
  const numCols = halfPage
    ? (league.matches.length > 55 ? 3 : 2)
    : (league.matches.length > 65 ? 3 : weekNums.length > 10 ? 2 : 1);
  const colSize = Math.ceil(weekNums.length / numCols);
  const columns = Array.from({ length: numCols }, (_, i) => weekNums.slice(i * colSize, (i + 1) * colSize));

  const shortDate = (iso) =>
    iso ? new Date(iso + "T00:00:00").toLocaleDateString(undefined, { day: "numeric", month: "short" }) : "TBC";

  const fullDate = (iso) => (iso ? formatDateLong(iso) : "TBC");

  const renderTable = (colWeeks, key) => (
    <table className="fixtures-mini-table" key={key}>
      <thead>
        <tr>
          <th>Wk</th><th>Date</th><th>Rk</th><th>Home</th><th>Away</th><th>Score</th>
        </tr>
      </thead>
      <tbody>
        {colWeeks.map((w) =>
          weeks[w]
            .sort((a, b) => a.rink - b.rink)
            .map((m, i) => (
              <tr key={m.id}>
                <td>{i === 0 ? w + 1 : ""}</td>
                <td>{halfPage ? shortDate(m.date) : fullDate(m.date)}</td>
                <td>{m.rink}</td>
                <td>{league.teams[m.home]}</td>
                <td>{league.teams[m.away]}</td>
                <td>{m.played ? `${m.homeScore} - ${m.awayScore}` : ""}</td>
              </tr>
            ))
        )}
      </tbody>
    </table>
  );

  return (
    <div
      className={`print-sheet fixtures-half-sheet${halfPage ? " fixtures-half-sheet-bordered fixtures-compact" : " fixtures-spacious"}`}
      style={pageBreakBefore ? { pageBreakBefore: "always" } : undefined}
    >
      <style>{`
        @media print {
          @page { margin: ${halfPage ? "0.8cm" : "1.4cm"}; }
          .fixtures-compact { break-inside: avoid; }
        }
        .fixtures-compact { padding: 4pt 8pt; }
        .fixtures-half-sheet-bordered { border-bottom: 1px dashed #999; padding-bottom: 6pt; }
        .fixtures-spacious { padding: 10pt 6pt; }
        .fixtures-half-sheet-columns { display: flex; gap: ${halfPage ? "8pt" : "20pt"}; }
        .fixtures-compact .fixtures-mini-table { font-size: 7pt; line-height: 1.05; }
        .fixtures-compact .fixtures-mini-table th { padding: 0.5pt 2pt; font-size: 7pt; }
        .fixtures-compact .fixtures-mini-table td { padding: 0.4pt 2pt; }
        .fixtures-spacious .fixtures-mini-table { font-size: 10pt; line-height: 1.35; }
        .fixtures-spacious .fixtures-mini-table th { padding: 2.5pt 7pt; font-size: 10pt; }
        .fixtures-spacious .fixtures-mini-table td { padding: 2pt 7pt; }
        .fixtures-mini-table { flex: 1; width: 0; border-collapse: collapse; }
        .fixtures-mini-table th { text-align: left; border-bottom: 1.5pt solid #222; }
        .fixtures-mini-table td { border-bottom: 0.5pt solid #ddd; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
      `}</style>
      <div style={{ display: "flex", alignItems: "center", gap: halfPage ? "6pt" : "12pt", marginBottom: halfPage ? "2pt" : "10pt" }}>
        <img src={CLUB_LOGO} alt="Club crest" style={{ height: halfPage ? "16pt" : "34pt", width: "auto" }} />
        {halfPage ? (
          <>
            <div style={{ fontFamily: "serif", fontWeight: "bold", fontSize: "9pt" }}>
              Hatfield Indoor Bowls Leagues &middot; {meta.name} &middot; {seasonLabel}
            </div>
            <div style={{ fontSize: "6.5pt", color: "#555", marginLeft: "auto" }}>
              {league.teams.join(", ")}
            </div>
          </>
        ) : (
          <div>
            <div style={{ fontFamily: "serif", fontWeight: "bold", fontSize: "20pt" }}>Hatfield Indoor Bowls Leagues</div>
            <div style={{ fontFamily: "serif", fontSize: "14pt" }}>{meta.name} &middot; {seasonLabel} season</div>
            <div style={{ fontSize: "9pt", color: "#555", marginTop: "2pt" }}>
              {league.size} teams: {league.teams.join(", ")}
            </div>
          </div>
        )}
      </div>
      <div className="fixtures-half-sheet-columns">
        {columns.map((col, i) => col.length > 0 && renderTable(col, i))}
      </div>
    </div>
  );
}

function Masthead({ view, setView, onLogout, data }) {
  const loggedIn = view === "admin" || view === "leader";
  const startYear = data?.seasonYear ?? defaultSeasonYear();
  const seasonLabel = `${startYear}/${String(startYear + 1).slice(-2)}`;
  return (
    <header className="bg-emerald-900 text-amber-50 border-b-4 border-amber-600">
      <div className="max-w-5xl mx-auto px-4 py-5 flex items-center justify-between flex-wrap gap-3">
        <div className="flex items-center gap-3">
          <img src={CLUB_LOGO} alt="Club crest" className="h-12 w-auto drop-shadow" />
          <div>
            <h1 className="font-serif text-2xl tracking-wide leading-none">Hatfield Indoor Bowls Leagues</h1>
            <p className="text-amber-200 text-xs mt-1 tracking-widest uppercase">{seasonLabel}</p>
          </div>
        </div>
        <div className="flex items-center gap-2 text-sm">
          {!loggedIn && (
            <>
              <button
                onClick={() => setView("leader-login")}
                className="px-3 py-1.5 rounded border border-amber-400 text-amber-100 hover:bg-emerald-800 transition"
              >
                Team leader
              </button>
              <button
                onClick={() => setView("admin-login")}
                className="px-3 py-1.5 rounded bg-amber-600 text-emerald-950 font-medium hover:bg-amber-500 transition flex items-center gap-1"
              >
                <ShieldCheck size={15} /> Admin
              </button>
            </>
          )}
          {loggedIn && (
            <button
              onClick={onLogout}
              className="px-3 py-1.5 rounded border border-amber-400 text-amber-100 hover:bg-emerald-800 transition flex items-center gap-1"
            >
              <LogOut size={15} /> Sign out
            </button>
          )}
        </div>
      </div>
    </header>
  );
}

function LeagueTabs({ activeLeagueId, setActiveLeagueId, data }) {
  return (
    <div className="flex flex-wrap gap-2 mb-6">
      {LEAGUES.map((l) => {
        const league = data.leagues[l.id];
        const active = l.id === activeLeagueId;
        return (
          <button
            key={l.id}
            onClick={() => setActiveLeagueId(l.id)}
            className={`px-4 py-2 rounded-t-md font-serif text-sm border-b-2 transition flex items-center gap-1.5 ${
              active
                ? "bg-white border-amber-600 text-emerald-900 shadow-sm"
                : "bg-stone-100 border-transparent text-stone-500 hover:text-emerald-800"
            }`}
          >
            {l.name}
            {league.locked && <Lock size={12} className="text-stone-400" />}
            {!league.size && <span className="text-[10px] text-stone-400">(not set)</span>}
          </button>
        );
      })}
    </div>
  );
}

