function PublicView({ data, activeLeagueId, setActiveLeagueId, onPrintLeague }) {
  const league = data.leagues[activeLeagueId];
  const meta = LEAGUES.find((l) => l.id === activeLeagueId);
  const standings = computeStandings(league);

  return (
    <main className="max-w-5xl mx-auto px-4 pt-8 pb-16">
      <LeagueTabs activeLeagueId={activeLeagueId} setActiveLeagueId={setActiveLeagueId} data={data} />

      {!league.size ? (
        <EmptyState text={`${meta.name} hasn't been set up yet. Check back once the admin publishes teams.`} />
      ) : (
        <div className="grid md:grid-cols-2 gap-8">
          <section>
            <h2 className="font-serif text-lg text-emerald-900 mb-3 flex items-center gap-2">
              <Trophy size={16} className="text-amber-600" /> League table
            </h2>
            <StandingsTable rows={standings} />
          </section>
          <section>
            <div className="flex items-center justify-between mb-3">
              <h2 className="font-serif text-lg text-emerald-900 flex items-center gap-2">
                <Calendar size={16} className="text-amber-600" /> Fixtures &amp; results
              </h2>
              {league.matches.length > 0 && (
                <button
                  onClick={() => onPrintLeague(activeLeagueId)}
                  className="text-xs px-2.5 py-1.5 rounded border border-stone-300 text-stone-600 hover:bg-stone-100 flex items-center gap-1"
                >
                  <Printer size={13} /> Print
                </button>
              )}
            </div>
            <FixturesList league={league} />
          </section>
        </div>
      )}
    </main>
  );
}

function EmptyState({ text }) {
  return (
    <div className="bg-white border border-dashed border-stone-300 rounded-lg p-10 text-center text-stone-500">
      {text}
    </div>
  );
}

function StandingsTable({ rows }) {
  if (rows.length === 0) return <EmptyState text="No teams entered yet." />;
  return (
    <div className="overflow-x-auto bg-white rounded-lg border border-stone-200 shadow-sm">
      <table className="w-full text-sm">
        <thead>
          <tr className="bg-emerald-900 text-amber-50 font-serif">
            <th className="text-left py-2 px-2">#</th>
            <th className="text-left py-2 px-2">Team</th>
            <th className="px-2">P</th>
            <th className="px-2">W</th>
            <th className="px-2">D</th>
            <th className="px-2">L</th>
            <th className="px-2">F</th>
            <th className="px-2">A</th>
            <th className="px-2">Diff</th>
            <th className="px-2 font-bold">Pts</th>
          </tr>
        </thead>
        <tbody className="font-mono">
          {rows.map((r, i) => (
            <tr key={r.idx} className={i % 2 === 0 ? "bg-stone-50" : "bg-white"}>
              <td className="py-1.5 px-2 text-stone-500">{i + 1}</td>
              <td className="py-1.5 px-2 font-sans font-medium text-stone-800">{r.name}</td>
              <td className="px-2 text-center">{r.p}</td>
              <td className="px-2 text-center">{r.w}</td>
              <td className="px-2 text-center">{r.d}</td>
              <td className="px-2 text-center">{r.l}</td>
              <td className="px-2 text-center">{r.f}</td>
              <td className="px-2 text-center">{r.a}</td>
              <td className="px-2 text-center">{r.diff > 0 ? `+${r.diff}` : r.diff}</td>
              <td className="px-2 text-center font-bold text-emerald-800">{r.pts}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

function FixturesList({ league, onScoreClick }) {
  if (league.matches.length === 0) return <EmptyState text="Fixtures haven't been generated yet." />;
  const weeks = {};
  league.matches.forEach((m) => {
    weeks[m.week] = weeks[m.week] || [];
    weeks[m.week].push(m);
  });
  const weekNums = Object.keys(weeks).map(Number).sort((a, b) => a - b);
  return (
    <div className="space-y-4 max-h-[32rem] overflow-y-auto pr-1">
      {weekNums.map((w) => (
        <div key={w} className="bg-white rounded-lg border border-stone-200 shadow-sm">
          <div className="bg-stone-100 px-3 py-1.5 rounded-t-lg text-xs font-serif text-stone-600 flex justify-between">
            <span>Week {w + 1}</span>
            <span>{weeks[w][0].date ? new Date(weeks[w][0].date).toLocaleDateString(undefined, { day: "numeric", month: "short", year: "numeric" }) : "Date TBC"}</span>
          </div>
          <ul className="divide-y divide-stone-100">
            {weeks[w].map((m) => (
              <li
                key={m.id}
                className={`px-3 py-2 flex items-center justify-between text-sm ${onScoreClick ? "cursor-pointer hover:bg-amber-50" : ""}`}
                onClick={() => onScoreClick && onScoreClick(m)}
              >
                <div className="flex items-center gap-2 min-w-0">
                  <RinkBadge n={m.rink} />
                  <span className="truncate">
                    <span className={m.played && m.homeScore > m.awayScore ? "font-semibold text-emerald-800" : ""}>{league.teams[m.home]}</span>
                    {" "}v{" "}
                    <span className={m.played && m.awayScore > m.homeScore ? "font-semibold text-emerald-800" : ""}>{league.teams[m.away]}</span>
                  </span>
                </div>
                <span className="font-mono text-stone-600 shrink-0 ml-2">
                  {m.played ? `${m.homeScore} - ${m.awayScore}` : "vs"}
                </span>
              </li>
            ))}
          </ul>
        </div>
      ))}
    </div>
  );
}

